uint32_t getULong(const byte* buf, ByteOrder byteOrder) {
  if (byteOrder == littleEndian) {
    return buf[3] << 24 | buf[2] << 16 | buf[1] << 8 | buf[0];
  }
  return buf[0] << 24 | buf[1] << 16 | buf[2] << 8 | buf[3];
}

